// @ts-check
/** @param {{ instanceId: string, state: import("./product-types.js").OfficePageState }} input @returns {string} */
export function renderHtml({ instanceId, state }) {
    const payload = JSON.stringify(state).replaceAll("<", "\\u003c").replaceAll("\u2028", "\\u2028").replaceAll("\u2029", "\\u2029");
    const panel = instanceId.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character] ?? character);
    const layout = [...instanceId].reduce((value, character) => Math.imul(value ^ (character.codePointAt(0) ?? 0), 16777619) >>> 0, 2166136261) % 4;
    return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Pixel Agents · Office</title><link rel="stylesheet" href="/office.css"></head>
<body><a class="skip-link" href="#office-floor">Skip to office</a><main class="app" data-instance="${panel}">
<header class="topbar"><div class="brand"><span class="brand-mark" aria-hidden="true">✦</span><h1>Pixel Agents <span>Office</span></h1></div><time id="clock" aria-label="Local time"></time></header>
<section class="statusbar" aria-label="Source health"><div id="connection">Connecting to sources…</div><div class="source-actions"><button id="refresh" type="button">↻ Refresh</button><button id="codex" type="button">Enable local Codex</button></div></section>
<p id="notice" class="notice" role="status" aria-live="polite" hidden></p>
<div class="workspace"><section class="office-panel" aria-labelledby="floor-title"><header class="panel-heading"><h2 id="floor-title">Office</h2><span id="occupancy" class="count">Loading agents</span></header>
<div class="floor-scroll"><div id="office-floor" class="office-floor layout-${layout}" tabindex="-1"><div class="office-wall" aria-hidden="true"><div id="zone-window" data-zone="window" class="pixel-window"><i></i></div><img class="wall-decoration" src="/assets/wall-art.svg" alt=""><div class="wall-clock"></div><div id="zone-bookshelf" data-zone="bookshelf" class="bookshelf"><i></i><i></i><i></i><i></i><i></i></div><div class="pixel-window second"><i></i></div><span id="wall-side-exit" class="wall-side-exit"></span></div><div class="floor-decor" aria-hidden="true"><span id="zone-desk-west" data-zone="desk-west" class="workstation-anchor west"></span><span id="zone-desk-east" data-zone="desk-east" class="workstation-anchor east"></span></div><div id="agent-layer" class="cluster-grid"><p class="empty-state">Loading agents…</p></div><div id="office-aisle" class="office-aisle" aria-hidden="true"></div><div class="common-area" aria-hidden="true"><div class="plant-corner-layout"><img id="zone-plant-corner" data-zone="plant-corner" src="/assets/plant.svg" alt=""></div><div class="common-table-layout"><img id="zone-common-table" data-zone="common-table" class="common-table-art" src="/assets/common-table.svg" alt=""><img class="table-chair north" src="/assets/chair.svg" alt=""><img class="table-chair south" src="/assets/chair.svg" alt=""><img class="table-chair west" src="/assets/chair.svg" alt=""><img class="table-chair east" src="/assets/chair.svg" alt=""></div><div class="coffee-station-layout"><img id="zone-coffee-station" data-zone="coffee-station" class="coffee-station-art" src="/assets/coffee-station.svg" alt=""></div><div id="zone-waste-bin" class="shared-waste-station"><img src="/assets/bin.svg" alt=""><img src="/assets/recycling.svg" alt=""></div></div><div id="zone-props" class="zone-props" role="group" aria-label="Decorative shared-zone props"></div><div id="ambience" class="ambience" aria-label="Decorative office effects"></div></div></div>
<footer class="floor-footer"><span><span class="legend-dot working"></span> Working <span class="legend-dot waiting"></span> Waiting <span class="legend-dot idle"></span> Idle <span class="legend-dot unknown"></span> Unknown</span></footer></section>
<aside id="details" class="details panel" aria-labelledby="details-title"><h2 id="details-title">Agent details</h2><div class="detail-empty" aria-hidden="true">✧</div></aside></div>
<div class="lower-grid"><section class="panel roster-panel" aria-labelledby="roster-title"><header class="section-heading"><h2 id="roster-title">Agents</h2><span id="roster-count" class="count">0 agents</span></header><div id="roster" class="roster"></div></section><section class="panel feed-panel" aria-labelledby="feed-title"><header class="section-heading"><h2 id="feed-title">Recent activity</h2><span class="feed-label">Observed</span></header><ol id="feed" class="feed"><li class="muted">No observed activity yet.</li></ol></section></div>
<section class="settings panel" aria-labelledby="settings-title"><header class="section-heading"><h2 id="settings-title">Preferences</h2></header><div class="preference-grid"><label class="toggle"><input id="hide-titles" type="checkbox"><span>Hide session titles</span></label><label class="toggle"><input id="show-ended" type="checkbox"><span>Show ended agents</span></label><label class="toggle"><input id="vignettes" type="checkbox"><span>Office scenes</span></label><label class="toggle"><input id="dialogue" type="checkbox"><span>Character dialogue</span></label></div><p id="preference-status" class="muted" role="status"></p></section>
<details id="coverage" class="coverage panel"><summary>Source details</summary><div id="coverage-content"></div><p class="muted">This view is read-only and cannot start, navigate, or control provider sessions. Missing events do not prove completion. Activity sources are separate from model and billing routes. Hidden titles may contain sensitive text; motifs are derived only from titles. Office scenes and dialogue are presentation, not provider activity.</p></details>
<noscript><p class="notice">JavaScript is required to show current activity.</p></noscript>
</main><script id="office-state" type="application/json">${payload}</script><script type="module" src="/office-client.js"></script></body></html>`;
}
